/** Build a player entity at the given world position for flush tests.
 *
 * Returns the persisted ship id so callers can match against
 * `repo.listShipsBySystem(...)`. The entity id format is
 * `entity:<shipId>` (TASK-13 entity factory).
 */
async function seedPlayer(
  shard: Shard,
  playerId: string,
  callsign: string,
  pos: { x: number; y: number; z: number },
  classId: ShipClassId = "scout",
  hull?: number,
  shields?: number,
): Promise<string> {
  const shipCls = SHIP_CLASSES[classId];
  // Caller passes a deterministic id so the entity ↔ repo row can be
  // correlated by string. The flush path extracts the ship id from
  // `entity:<shipId>` so the test must keep the same prefix.
  const shipId = `ship-${playerId}`;
  spawnShip(shard, {
    shipId,
    playerId,
    callsign,
    classId,
    hull: hull ?? shipCls.hull,
    shields: shields ?? shipCls.shieldCapacity,
    pos,
    vel: { x: 0, y: 0, z: 0 },
    quat: { x: 0, y: 0, z: 0, w: 1 },
    regime: "space",
    originPlanetId: null,
    onPad: null,
    bindConnId: undefined,
  });
  return shipId;
}

